import{_ as p,a0 as o,w as r,s as l,ao as d,I as s,x as a,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"在linux上使用交換文件擴展交換空間 | LCTT x X-CMD","titleTemplate":false,"description":"在linux上使用交換文件擴展交換空間 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在linux上使用交換文件擴展交換空間 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在linux上使用交換文件擴展交換空間 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150515 Extend Swap Space using Swap file in Linux","title":"在linux上使用交換文件擴展交換空間","tag":"201506","desc":""},"relativePath":"201506/20150515 Extend Swap Space using Swap file in Linux.md","filePath":"[post].md"}'),u={name:"201506/20150515 Extend Swap Space using Swap file in Linux.md"};function w(f,e,x,h,c,m){const t=o("Link");return r(),l("div",null,[e[13]||(e[13]=d(`<h1 id="在linux上使用交換文件擴展交換空間" tabindex="-1">在linux上使用交換文件擴展交換空間 <a class="header-anchor" href="#在linux上使用交換文件擴展交換空間" aria-label="Permalink to “在linux上使用交換文件擴展交換空間”">​</a></h1><p>想像一種情景，當我們的Linux系統用盡交換空間時，在這種情況下，我們想要使用swap分區擴展交換空間，但在某些情況下磁盤上已經沒有可用的空閒分區了，致使我們不能把它擴大。</p><p>因此，在這種情況下，我們可以使用交換文件增加swap空間。</p><h3 id="以下是使用交換文件在linux上擴展swap空間的方法" tabindex="-1">以下是使用交換文件在Linux上擴展swap空間的方法 <a class="header-anchor" href="#以下是使用交換文件在linux上擴展swap空間的方法" aria-label="Permalink to “以下是使用交換文件在Linux上擴展swap空間的方法”">​</a></h3><p>讓我們首先檢查現有的交換空間/分區的大小，使用命令 ‘<strong>free -m‘</strong> 或者 ‘<strong>swapon -s</strong>‘</p><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/06/free-output-with-swap.jpg" alt=""> free-output-with-swap</p><p>我的交換分區大小是2 GB，我們將把交換空間擴展1GB。</p><h4 id="第一步-使用下面的dd命令創建大小為1gb交換文件" tabindex="-1">第一步：使用下面的dd命令創建大小為1GB交換文件 <a class="header-anchor" href="#第一步-使用下面的dd命令創建大小為1gb交換文件" aria-label="Permalink to “第一步：使用下面的dd命令創建大小為1GB交換文件”">​</a></h4><pre><code>[root@linuxtechi ~]# dd if=/dev/zero of=/swap_file bs=1G count=1
1+0 records in
1+0 records out
1073741824 bytes (1.1 GB) copied, 414.898 s, 2.6 MB/s
[root@linuxtechi ~]#
</code></pre><p>根據你的需要替換 ‘<strong>bs</strong>‘ 和 ‘<strong>count</strong>‘ 的大小.</p><h4 id="第二步-設置交換文件權限為600" tabindex="-1">第二步：設置交換文件權限為600 <a class="header-anchor" href="#第二步-設置交換文件權限為600" aria-label="Permalink to “第二步：設置交換文件權限為600”">​</a></h4><pre><code>[root@linuxtechi ~]# chmod 600 /swap_file
</code></pre><h4 id="第三步-用文件開啓交換區-swap-file" tabindex="-1">第三步：用文件開啓交換區（swap_file）#### <a class="header-anchor" href="#第三步-用文件開啓交換區-swap-file" aria-label="Permalink to “第三步：用文件開啓交換區（swap_file）####”">​</a></h4><p>用mkswap命令開啓交換區</p><pre><code>[root@linuxtechi ~]# mkswap /swap_file
Setting up swapspace version 1, size = 1048572 KiB
no label, UUID=f7b3ae59-c09a-4dc2-ba4d-c02abb7db33b
[root@linuxtechi ~]#
</code></pre><h4 id="第四步-在fstab文件中添加交換文件條目" tabindex="-1">第四步：在fstab文件中添加交換文件條目 <a class="header-anchor" href="#第四步-在fstab文件中添加交換文件條目" aria-label="Permalink to “第四步：在fstab文件中添加交換文件條目”">​</a></h4><p>在fstab文件中添加以下條目，以便交換文件每次重啓後互能繼續使用.</p><pre><code>/swap_file  swap  swap  defaults  0 0
</code></pre><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/06/swap-file-fstab-entry.jpg" alt="swap-file-fstab-entry"></p><h4 id="第五步-用命令-mkswap-on-啓用交換文件" tabindex="-1">第五步：用命令 ‘mkswap on’ 啓用交換文件. <a class="header-anchor" href="#第五步-用命令-mkswap-on-啓用交換文件" aria-label="Permalink to “第五步：用命令 ‘mkswap on’ 啓用交換文件.”">​</a></h4><pre><code>[root@linuxtechi ~]# swapon /swap_file
[root@linuxtechi ~]#
</code></pre><h4 id="第六步-現在查看交換空間" tabindex="-1">第六步：現在查看交換空間 <a class="header-anchor" href="#第六步-現在查看交換空間" aria-label="Permalink to “第六步：現在查看交換空間”">​</a></h4><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/06/swap-space-after-extension.jpg" alt="swap-space-after-extension"></p><p><strong>Note</strong>: 為了避免出現意外的情況，如下所示使用swapoff命令關閉它，僅在需要使用時，使用步驟5所示的swapon命令，重新啓用交換文件。</p><pre><code>[root@linuxtechi ~]# swapoff /swap_file
[root@linuxtechi ~]#
</code></pre><p>請分享您的寶貴意見或者評論此文章。</p><hr>`,27)),s("p",null,[e[1]||(e[1]=a("via: ",-1)),n(t,{href:"http://www.linuxtechi.com/extend-swap-space-using-swap-file-in-linux/"},{default:i(()=>[...e[0]||(e[0]=[a("http://www.linuxtechi.com/extend-swap-space-using-swap-file-in-linux/",-1)])]),_:1})]),s("p",null,[e[5]||(e[5]=a("作者：",-1)),n(t,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:i(()=>[...e[2]||(e[2]=[a("Pradeep Kumar",-1)])]),_:1}),e[6]||(e[6]=a(" 譯者：",-1)),n(t,{href:"https://github.com/strugglingyouth"},{default:i(()=>[...e[3]||(e[3]=[a("strugglingyouth",-1)])]),_:1}),e[7]||(e[7]=a(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),s("p",null,[e[10]||(e[10]=a("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原創翻譯，",-1)),n(t,{href:"https://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[a("Linux中國",-1)])]),_:1}),e[12]||(e[12]=a(" 榮譽推出",-1))])])}const _=p(u,[["render",w]]);export{T as __pageData,_ as default};
